import CoreGraphics
import Foundation
import GlintCore
import ImageIO
import MLX
import Testing

@testable import GlintEmbedding

/// Parity gate from the PRD: Swift outputs must match the Python reference at cosine ≥ 0.999
/// with identical token ids before a model build ships.
///
/// Needs the checkpoint and fixtures generated by `scripts/model/make_parity_fixtures.py`:
///   GLINT_EG2_DIR=<checkpoint dir>  GLINT_EG2_FIXTURES=<fixtures dir>
/// MLX needs Metal shaders, so run through Xcode (`TEST_RUNNER_` forwards the variables):
///   TEST_RUNNER_GLINT_EG2_DIR=… TEST_RUNNER_GLINT_EG2_FIXTURES=… \
///   xcodebuild test -scheme Glint-Package -destination 'platform=macOS' -only-testing:GlintEmbeddingTests
@Suite(
    "EmbeddingGemma 2 parity", .serialized,
    .enabled(if: ProcessInfo.processInfo.environment["GLINT_EG2_DIR"] != nil))
struct EmbeddingGemma2ParityTests {
    static let modelDirectory = URL(fileURLWithPath: ProcessInfo.processInfo.environment["GLINT_EG2_DIR"] ?? "/")
    static let fixtures = URL(fileURLWithPath: ProcessInfo.processInfo.environment["GLINT_EG2_FIXTURES"] ?? "/")
    static let threshold: Float = 0.999

    struct TextFixture: Decodable {
        var text: String
        var ids: [Int]
        var embedding: [Float]
    }

    struct Tensor: Decodable {
        var shape: [Int]
        var values: [Float]
    }

    struct MediaFixture: Decodable {
        var name: String
        var ids: [Int]
        var embedding: [Float]
        var pixelValues: Tensor?
        var imagePositionIds: Tensor?
        var inputFeatures: Tensor?
        var inputFeaturesMask: Tensor?

        enum CodingKeys: String, CodingKey {
            case name, ids, embedding
            case pixelValues = "pixel_values"
            case imagePositionIds = "image_position_ids"
            case inputFeatures = "input_features"
            case inputFeaturesMask = "input_features_mask"
        }
    }

    static func cosine(_ a: [Float], _ b: [Float]) -> Float {
        var dot: Float = 0
        var na: Float = 0
        var nb: Float = 0
        for (x, y) in zip(a, b) {
            dot += x * y
            na += x * x
            nb += y * y
        }
        return dot / max((na * nb).squareRoot(), 1e-12)
    }

    static func media(_ name: String) throws -> MediaFixture {
        struct File: Decodable { var fixtures: [MediaFixture] }
        let file = try JSONDecoder().decode(File.self, from: Data(contentsOf: fixtures.appendingPathComponent("media_fixtures.json")))
        return try #require(file.fixtures.first { $0.name == name })
    }

    static func image(_ name: String) throws -> CGImage {
        let source = try #require(CGImageSourceCreateWithURL(fixtures.appendingPathComponent(name) as CFURL, nil))
        return try #require(CGImageSourceCreateImageAtIndex(source, 0, nil))
    }

    static func load(_ towers: EG2Towers) async throws -> (EG2Runtime, EG2Processor) {
        let config = try EG2Configuration.load(from: modelDirectory)
        let tokenizer = try await TokenizerLoader.load(modelDirectory)
        return (
            try EG2Runtime(directory: modelDirectory, config: config, tokenizer: tokenizer, towers: towers),
            EG2Processor(tokenizer: tokenizer, config: config)
        )
    }

    @Test func textMatchesReference() async throws {
        struct File: Decodable { var fixtures: [TextFixture] }
        let file = try JSONDecoder().decode(File.self, from: Data(contentsOf: Self.fixtures.appendingPathComponent("text_fixtures.json")))
        let (runtime, processor) = try await Self.load(.text)
        for fixture in file.fixtures {
            let ids =
                [EG2Processor.bosToken] + processor.tokenizer.encode(text: fixture.text, addSpecialTokens: false) + [EG2Processor.eosToken]
            #expect(ids == fixture.ids, "token ids differ for: \(fixture.text.prefix(40))")
        }
        let vectors = try await runtime.embedRaw(file.fixtures.map(\.text))
        for (fixture, vector) in zip(file.fixtures, vectors) {
            let similarity = Self.cosine(vector, fixture.embedding)
            print("text parity \(similarity) — \(fixture.text.prefix(48))")
            #expect(similarity >= Self.threshold)
        }
    }

    @Test(arguments: ["photo", "document"])
    func imagePreprocessingMatchesReference(name: String) throws {
        let fixture = try Self.media(name)
        let reference = try #require(fixture.pixelValues)
        let positions = try #require(fixture.imagePositionIds)
        let output = try #require(EG2ImageProcessor(maxSoftTokens: 280).process(try Self.image("\(name).png")))
        #expect(output.positions.map(Float.init) == positions.values)
        let maxDifference = zip(output.patches, reference.values).map { abs($0 - $1) }.max() ?? 0
        print("\(name) pixels max |Δ| = \(maxDifference)")
        #expect(maxDifference <= 1.0 / 255 + 1e-6, "resize differs from Pillow by more than one 8-bit level")
        #expect(output.softTokens + 4 == fixture.ids.count)
    }

    @Test(arguments: ["photo", "document", "photo_with_text"])
    func imageEmbeddingMatchesReference(name: String) async throws {
        let fixture = try Self.media(name)
        let (runtime, processor) = try await Self.load([.text, .vision])
        // Model-only parity: reference ids and preprocessed pixels.
        let pixels = try #require(fixture.pixelValues)
        let positions = try #require(fixture.imagePositionIds)
        let batch = EG2Batch(
            inputIDs: MLXArray(fixture.ids.map(Int32.init), [1, fixture.ids.count]),
            attentionMask: MLXArray.ones([1, fixture.ids.count], type: Int32.self),
            pixelValues: MLXArray(pixels.values, pixels.shape),
            imagePositionIDs: MLXArray(positions.values.map(Int32.init), positions.shape))
        let modelOnly = try await runtime.embed(batch: batch)
        let modelSimilarity = Self.cosine(modelOnly, fixture.embedding)
        print("\(name) model parity \(modelSimilarity)")
        #expect(modelSimilarity >= Self.threshold)

        // End to end through the Swift processor.
        let input: EmbeddingInput =
            name == "photo_with_text"
            ? .interleaved([.image(try Self.image("photo.png")), .text("mountain by the beach")])
            : .image(try Self.image("\(name).png"))
        let item = try processor.prepare(input, purpose: .document)
        #expect(item.ids.map(Int.init) == fixture.ids)
        let endToEnd = try await runtime.embed([input], purpose: .document)[0]
        let similarity = Self.cosine(endToEnd, fixture.embedding)
        print("\(name) end-to-end parity \(similarity)")
        #expect(similarity >= Self.threshold)
    }

    @Test func audioMatchesReference() async throws {
        let fixture = try Self.media("audio")
        let features = try #require(fixture.inputFeatures)
        let mask = try #require(fixture.inputFeaturesMask)
        let samples = try Self.wavSamples(Self.fixtures.appendingPathComponent("audio.wav"))

        let extracted = EG2AudioFeatureExtractor()(samples)
        #expect(extracted.features.shape == Array(features.shape.dropFirst()))
        #expect(extracted.mask == mask.values.map { $0 != 0 })
        let maxDifference = abs(extracted.features.flattened() - MLXArray(features.values)).max().item(Float.self)
        print("audio features max |Δ| = \(maxDifference)")
        // float32 FFT here versus numpy's float64; the log domain amplifies near-floor bins.
        #expect(maxDifference < 5e-3)

        let (runtime, processor) = try await Self.load([.text, .audio])
        let item = try processor.prepare(.audio(AudioClip(samples: samples)), purpose: .document)
        #expect(item.ids.map(Int.init) == fixture.ids)
        let vector = try await runtime.embed([.audio(AudioClip(samples: samples))], purpose: .document)[0]
        let similarity = Self.cosine(vector, fixture.embedding)
        print("audio parity \(similarity)")
        #expect(similarity >= Self.threshold)
    }

    /// Latency and memory of the model as Glint uses it (printed; budgets are checked in the
    /// performance suite on the reference Mac).
    @Test func reportsLatencyAndMemory() async throws {
        let (runtime, _) = try await Self.load(.text)
        let textOnlyBytes = Memory.activeMemory
        _ = try await runtime.embed([.text("warm up")], purpose: .query)
        var samples: [Double] = []
        for query in ["crowd cheering at night", "pricing chart for the acme pitch", "when the client mentioned the deadline", "blue mug"] {
            for _ in 0..<10 {
                let clock = ContinuousClock.now
                _ = try await runtime.embed([.text(query)], purpose: .query)
                samples.append(Double((ContinuousClock.now - clock).components.attoseconds) / 1e15)
            }
        }
        samples.sort()
        print(
            "query p50 \(samples[samples.count / 2]) ms, p95 \(samples[Int(Double(samples.count) * 0.95)]) ms; text tower active memory \(textOnlyBytes / 1_048_576) MB"
        )

        let (full, _) = try await Self.load(.all)
        let photo = try Self.image("photo.png")
        _ = try await full.embed([.image(photo)], purpose: .document)
        var clock = ContinuousClock.now
        for _ in 0..<5 { _ = try await full.embed([.image(photo)], purpose: .document) }
        print("image \(Double((ContinuousClock.now - clock).components.attoseconds) / 5e15) ms each")
        let tenSeconds = AudioClip(samples: (0..<160_000).map { sin(Float($0) * 0.05) * 0.3 })
        _ = try await full.embed([.audio(tenSeconds)], purpose: .document)
        clock = ContinuousClock.now
        for _ in 0..<3 { _ = try await full.embed([.audio(tenSeconds)], purpose: .document) }
        print("10 s audio window \(Double((ContinuousClock.now - clock).components.attoseconds) / 3e15) ms each")
        let frames = Array(repeating: photo, count: 5)
        clock = ContinuousClock.now
        for _ in 0..<3 { _ = try await full.embed([.video(VideoClip(frames: frames, start: 0, end: 5))], purpose: .document) }
        print(
            "5 s video clip (5 frames) \(Double((ContinuousClock.now - clock).components.attoseconds) / 3e15) ms each; peak \(Memory.peakMemory / 1_048_576) MB"
        )
    }

    static func wavSamples(_ url: URL) throws -> [Float] {
        let data = try Data(contentsOf: url)
        let pcm = data.dropFirst(44)
        return stride(from: pcm.startIndex, to: pcm.endIndex - 1, by: 2).map { index in
            Float(Int16(littleEndian: Int16(pcm[index]) | Int16(pcm[index + 1]) << 8)) / 32_768
        }
    }
}
